CREATE OR REPLACE VIEW `view_clusterung_anwesenheit` AS
with dates as (select date_format(curdate() - interval 1 month,'%Y-%m-01') AS `mindate`,last_day(curdate() - interval 1 month) AS `maxdate`), datelist as (select `d`.`datum` AS `datum` from (`tbl_datum` `d` join `dates` on(`d`.`datum` between `dates`.`mindate` and `dates`.`maxdate`))), anwesenheit as (
  select b.`Datum` as `datum`, b.`Schicht` as `schicht`
       , sum(p.oe in ('PRD','Leitstand','Trainer') and p.taetigkeit not in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator')) + ifnull(v.prd,0) as `PRD/LS/Trainer`
       , sum(p.oe in ('PRD','Leitstand','Trainer') and p.taetigkeit = 'Teamleiter') as `PRD/LS/Trainer_TL`
       , sum(p.oe in ('WA','WE','BGL') and p.taetigkeit <> 'Schichtleiter') + ifnull(v.wa,0) + ifnull(v.we,0) + ifnull(v.bgl,0) - ifnull(v.yard,0) as `WA/WE/BGL`
       , sum(p.oe in ('WA','WE','BGL') and p.taetigkeit = 'Teamleiter') as `WA/WE/BGL_TL`
       , ifnull(v.yard,0) as `Yard`
       , sum(p.oe = 'QS' and p.taetigkeit <> 'Schichtleiter') + ifnull(v.qs,0) as `QS`
       , sum(p.oe = 'QS' and p.taetigkeit = 'Teamleiter') as `QS_TL`
       , sum(p.taetigkeit in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator')) as `Schichtleiter`
    from tbl_ueb_fz_buchungen b
    join datelist d on b.`Datum` = d.datum
    left join tbl_ueb_personalakte_scd p
      on b.`PersNr` = p.persnr_alt
     and b.`Datum` between p.gueltig_von and p.gueltig_bis
    left join tbl_stamm_kategorie_abteilung k on p.taetigkeit = k.`tätigkeit`
    left join tbl_import_verschiebung v on v.datum = b.`Datum` and v.schicht = b.`Schicht`
   where b.anwesenheit = 'anw'
     and k.kategorie not in ('admin','leitung (at)')
   group by b.`Datum`, b.`Schicht`
), fanf as (select `f`.`datum` AS `datum`,`f`.`oe` AS `oe`,`f`.`tätigkeit` AS `tätigkeit`,`f`.`beauftragung` AS `beauftragung`,`s`.`Schicht` AS `schicht` from ((`tbl_uebertrag_fanf` `f` left join `tbl_schichten` `s` on(`s`.`Schicht_int` = `f`.`schicht` and `s`.`Index` <= 3)) join `datelist` `d` on(`f`.`datum` = `d`.`datum`))), fanf2 as (select `f`.`datum` AS `datum`,`f`.`schicht` AS `schicht`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` not in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator') and `f`.`oe` in ('PRD','Leitstand','Trainer'))) - if(`f`.`schicht` = 'Früh',1,0) AS `PRD/LS/Trainer`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` = 'Teamleiter' and `f`.`oe` in ('PRD','Leitstand','Trainer'))) AS `PRD/LS/Trainer_TL`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` not in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator') and `f`.`oe` in ('WA','WE','BGL'))) - 2 AS `WA/WE/BGL`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` = 'Teamleiter' and `f`.`oe` in ('WA','WE','BGL'))) - 2 AS `WA/WE/BGL_TL`,2 AS `Yard`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` not in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator') and `f`.`oe` = 'QS')) AS `QS`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` = 'Teamleiter' and `f`.`oe` = 'QS')) AS `QS_TL`,sum(`f`.`beauftragung` * (`f`.`tätigkeit` in ('Schichtleiter','Trainingskoordinator','Qualifizierungskoordinator'))) + if(`f`.`schicht` = 'Früh',1,0) AS `Schichtleiter` from `fanf` `f` group by `f`.`datum`,`f`.`schicht`), basis as (select `a`.`datum` AS `datum`,`a`.`schicht` AS `schicht`,'Soll' AS `art`,`f`.`PRD/LS/Trainer` AS `PRD/LS/Trainer`,concat(round(`f`.`PRD/LS/Trainer` * 0.97,0),'-',round(`f`.`PRD/LS/Trainer` * 1.03,0)) AS `PRD_3%`,`f`.`PRD/LS/Trainer_TL` AS `PRD/LS/Trainer_TL`,`f`.`WA/WE/BGL` AS `WA/WE/BGL`,concat(round(`f`.`WA/WE/BGL` * 0.97,0),'-',round(`f`.`WA/WE/BGL` * 1.03,0)) AS `WA_WE_BGL_3%`,`f`.`WA/WE/BGL_TL` AS `WA/WE/BGL_TL`,`f`.`Yard` AS `Yard`,concat(round(`f`.`Yard` * 0.97,0),'-',round(`f`.`Yard` * 1.03,0)) AS `Yard_3%`,`f`.`QS` AS `QS`,concat(round(`f`.`QS` * 0.97,0),'-',round(`f`.`QS` * 1.03,0)) AS `QS_3%`,`f`.`QS_TL` AS `QS_TL`,`f`.`Schichtleiter` AS `Schichtleiter`,concat(round(`f`.`Schichtleiter` * 0.97,0),'-',round(`f`.`Schichtleiter` * 1.03,0)) AS `Schichtleiter_3%` from (`fanf2` `f` join `anwesenheit` `a` on(`a`.`datum` = `f`.`datum` and `a`.`schicht` = `f`.`schicht`)) union all select `a`.`datum` AS `datum`,`a`.`schicht` AS `schicht`,'Ist' AS `art`,`a`.`PRD/LS/Trainer` AS `PRD/LS/Trainer`,`a`.`PRD/LS/Trainer` / `f`.`PRD/LS/Trainer` - 1 AS `PRD/LS/Trainer_3%`,`a`.`PRD/LS/Trainer_TL` AS `PRD/LS/Trainer_TL`,`a`.`WA/WE/BGL` AS `WA/WE/BGL`,`a`.`WA/WE/BGL` / `f`.`WA/WE/BGL` - 1 AS `WA/WE/BGL_3%`,`a`.`WA/WE/BGL_TL` AS `WA/WE/BGL_TL`,`a`.`Yard` AS `Yard`,`a`.`Yard` / `f`.`Yard` - 1 AS `Yard_3%`,`a`.`QS` AS `QS`,`a`.`QS` / `f`.`QS` - 1 AS `QS_3%`,`a`.`QS_TL` AS `QS_TL`,`a`.`Schichtleiter` AS `Schichtleiter`,`a`.`Schichtleiter` / `f`.`Schichtleiter` - 1 AS `Schichtleiter_3%` from (`anwesenheit` `a` join `fanf2` `f` on(`a`.`datum` = `f`.`datum` and `a`.`schicht` = `f`.`schicht`)))select `basis`.`datum` AS `datum`,`basis`.`schicht` AS `schicht`,`basis`.`art` AS `art`,`basis`.`PRD/LS/Trainer` AS `PRD/LS/Trainer`,`basis`.`PRD_3%` AS `PRD_3%`,`basis`.`PRD/LS/Trainer_TL` AS `PRD/LS/Trainer_TL`,`basis`.`WA/WE/BGL` AS `WA/WE/BGL`,`basis`.`WA_WE_BGL_3%` AS `WA_WE_BGL_3%`,`basis`.`WA/WE/BGL_TL` AS `WA/WE/BGL_TL`,`basis`.`Yard` AS `Yard`,`basis`.`Yard_3%` AS `Yard_3%`,`basis`.`QS` AS `QS`,`basis`.`QS_3%` AS `QS_3%`,`basis`.`QS_TL` AS `QS_TL`,`basis`.`Schichtleiter` AS `Schichtleiter`,`basis`.`Schichtleiter_3%` AS `Schichtleiter_3%` from `basis` union all select `basis`.`datum` AS `datum`,'' AS `schicht`,`basis`.`art` AS `art`,sum(`basis`.`PRD/LS/Trainer`) AS `PRD/LS/Trainer`,'' AS `PRD/LS/Trainer_3%`,sum(`basis`.`PRD/LS/Trainer_TL`) AS `PRD/LS/Trainer_TL`,sum(`basis`.`WA/WE/BGL`) AS `WA/WE/BGL`,'' AS `WA_WE_BGL_3%`,sum(`basis`.`WA/WE/BGL_TL`) AS `WA/WE/BGL_TL`,sum(`basis`.`Yard`) AS `Yard`,'' AS `Yard_3%`,sum(`basis`.`QS`) AS `QS`,'' AS `QS_3%`,sum(`basis`.`QS_TL`) AS `QS_TL`,sum(`basis`.`Schichtleiter`) AS `Schichtleiter`,'' AS `Schichtleiter_3%` from `basis` group by `basis`.`datum`,`basis`.`art` order by `datum` desc,field(`art`,'Soll','Ist'),field(`schicht`,'','Spät','Früh','Nacht');
